def _get_activate_script(self) -> str:
    if self._name == "fish":
        suffix = ".fish"
    elif self._name in ("csh", "tcsh"):
        suffix = ".csh"
    elif self._name in ("powershell", "pwsh"):
        suffix = ".ps1"
    elif self._name == "cmd":
        suffix = ".bat"
    elif self._name == "nu":
        suffix = ".nu"
    else:
        suffix = ""

    return "activate" + suffix

def _get_source_command(self) -> str:
    if self._name in ("fish", "csh", "tcsh", "nu"):
        return "source"
    return "."
